---@param node table
---@return string[]|nil
function TreePassivesRU:GetStats(node)
    if not node then return nil end
    local skill = node.skill or node.id
    if not skill then return nil end
    return TreePassivesRU.statsBySkill[skill]
end

---@param node table
---@return string|nil
function TreePassivesRU:GetFlavour(node)
    if not node then return nil end
    local skill = node.skill or node.id
    if not skill then return nil end
    return TreePassivesRU.flavourBySkill[skill]
end

return TreePassivesRU
